<div class="section-heading"><h1><?= e($title) ?></h1><a class="button" href="<?= e(url('admin/noticias/nueva')) ?>">Crear noticia</a></div><form class="filters" method="get"><div class="field"><label for="filter-q">Buscar por título o contenido</label><input id="filter-q" type="search" name="q" value="<?= e($filters['q']) ?>" enterkeyhint="search"></div><div class="field"><label for="filter-status">Estado</label><select id="filter-status" name="status"><option value="">Todos</option><?php foreach (['borrador', 'revision', 'publicado', 'archivado'] as $status): ?><option value="<?= e($status) ?>"<?= $filters['status'] === $status ? ' selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></div><?php if ($filters['trash']): ?><input type="hidden" name="trash" value="1"><?php endif; ?><button class="button">Filtrar</button><a class="button button--quiet" href="<?= e(url('admin/noticias') . ($filters['trash'] ? '' : '?trash=1')) ?>"><?= $filters['trash'] ? 'Volver a noticias' : 'Ver papelera' ?></a></form>
<div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de noticias, desplazable"><table><caption><?= e($result['total']) ?> noticias encontradas</caption><thead><tr><th scope="col">Noticia</th><th scope="col">Estado</th><th scope="col">Autor</th><th scope="col">Acciones</th></tr></thead><tbody><?php foreach ($result['items'] as $item): ?><tr><td><?= e($item['title']) ?><small><?= e($item['category']) ?></small></td><td><span class="badge"><?= e($item['status']) ?></span><?php if ($item['published_at'] && strtotime($item['published_at']) > time()): ?><small>Programada</small><?php endif; ?></td><td><?= e($item['author']) ?></td><td><div class="actions"><?php if (!$filters['trash']): ?><a class="button button--quiet" href="<?= e(url('admin/noticias/' . $item['id'] . '/editar')) ?>">Editar<span class="sr-only"> <?= e($item['title']) ?></span></a><?php endif; ?><form method="post" action="<?= e(url('admin/noticias/' . $item['id'] . ($filters['trash'] ? '/restaurar' : '/eliminar'))) ?>"<?= !$filters['trash'] ? ' data-confirm' : '' ?>><?= csrf() ?><?php if (!$filters['trash']): ?><label class="check"><input type="checkbox" name="confirm" value="1" required> Confirmo eliminar <span class="sr-only"><?= e($item['title']) ?></span></label><?php endif; ?><button class="button <?= $filters['trash'] ? '' : 'button--danger' ?>"><?= $filters['trash'] ? 'Restaurar' : 'Eliminar' ?><span class="sr-only"> <?= e($item['title']) ?></span></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$result['items']): ?><p class="empty">No hay noticias aquí. Crea una noticia o cambia los filtros.</p><?php endif; ?><?php pagination($result, 'admin/noticias', ['q' => $filters['q'], 'status' => $filters['status'], 'trash' => $filters['trash'] ? '1' : '0']); ?>
